// RFID lab R8 Card friends.  uv run pio run -d labs/rfid-lab-r8 -e rfid-lab-r8 -t upload
// A playful lab for kids: every card is the home of a friend (a fox, a robot, a dragon, ...).
// Tap a card and its friend pops out on the screen, and in 3D in the app (esp32-labs/apps/friends-app),
// each with its own colours, dance, sound and sparkles. A new card is added by itself on its
// first tap; in the app you drag a friend onto it. Card 1 and card 2 show different friends.
//
// Built from R7's parts: the same driver and reader health checks, the same web libraries, the
// same admin token, the same Wi-Fi (saved by W1/W2). Only the UID is read; no card is written.
//
// Wiring: the screen from lesson 03 and the RC522 as in R1. Push button on GPIO 5 optional.
// Views: stage · friends   (button: click = next view)
// On-board LED: flashes in the friend's colour on a tap, breathes softly while waiting.
// Serial: help · status · token · token new · cards · give <number> <friend> · name <number> <name> ·
//         forget <number> · cast · reset
#include <Arduino.h>
#include <ArduinoJson.h>
#include <WiFi.h>
#include <esp_system.h>

#include "api_token.h"
#include "button.h"
#include "characters.h"
#include "color.h"
#include "connection.h"
#include "display.h"
#include "friend_views.h"
#include "friends.h"
#include "friends_api.h"
#include "pins.h"
#include "tap_reader.h"

namespace {

const char *const kViewNames[] = {"stage", "cards"};
constexpr int kViews = 2;

Display display;
Connection connection;
ApiToken token;
friends::List cardList;
TapReader reader(cardList);
FriendsApi api(cardList, reader, token);
Button external(PIN_BUTTON, "button");
Button boot(PIN_BOOT_BTN, "BOOT");

struct {
  int view = 0;
  Stage stage;
  std::vector<friends::Card> cards;
  uint32_t cardsVersion = 0, lastStatus = 0;
  bool apiStarted = false;
} state;

const char *resetReason() {
  switch (esp_reset_reason()) {
    case ESP_RST_POWERON: return "power on";
    case ESP_RST_SW: return "restart";
    case ESP_RST_PANIC: return "crash (panic)";
    case ESP_RST_INT_WDT:
    case ESP_RST_TASK_WDT:
    case ESP_RST_WDT: return "watchdog";
    case ESP_RST_BROWNOUT: return "brownout (supply dipped)";
    case ESP_RST_EXT: return "reset button";
    case ESP_RST_USB: return "USB";
    default: return "other";
  }
}

void printHelp() {
  Serial.println("\nRFID lab R8 Card friends  (rfid-lab-r8)");
  Serial.println("  status                Wi-Fi, address, reader chip, card count");
  Serial.println("  token                 the admin token for esp32-labs/apps/friends-app/.env (token new: replace it)");
  Serial.println("  cards                 every card and who lives on it");
  Serial.println("  cast                  the friends this firmware knows");
  Serial.println("  give <number> <id>    move a friend onto a card, e.g. give 1 fox (give 1 none: empty it)");
  Serial.println("  name <number> <name>  the friend's name on that card (name 1 -: back to its own)");
  Serial.println("  forget <number>       forget a card (it comes back empty on its next tap)");
  Serial.println("  reset                 hard reset of the reader chip");
  Serial.println("Button or BOOT: click = next view (stage, cards)");
}

void printStatus() {
  const bool joined = connection.state() == Connection::State::Connected;
  Serial.printf("Wi-Fi: %s %s | http://%s.local (%s) | app clients %u\n", joined ? "joined" : "not joined",
                connection.ssid().c_str(), Connection::kHostname, joined ? WiFi.localIP().toString().c_str() : "-",
                unsigned(api.clients()));
  const Stage &s = state.stage;
  Serial.printf("Reader chip 0x%02X (%s), %s | settings restored %u x | lost %u x | last problem: %s\n", s.chipVersion,
                rc522::versionName(s.chipVersion), s.irqMode ? "IRQ wire" : "polling", s.restores, s.lost,
                s.problem[0] ? s.problem : "none");
  Serial.printf("%d of %d cards | up %lu s | last start: %s | free heap %u B\n", cardList.count(), friends::List::kMax,
                millis() / 1000, resetReason(), unsigned(ESP.getFreeHeap()));
}

void printCards() {
  const auto list = cardList.list();
  Serial.printf("%u card%s\n", unsigned(list.size()), list.size() == 1 ? "" : "s");
  for (const friends::Card &c : list) {
    char uid[21];
    friends::uidToHex(c.uid, c.uidLen, uid, sizeof(uid));
    const cast::Character *who = cast::find(c.character);
    Serial.printf("  %2u  %-14s %-8s %-15s taps %lu\n", c.number, uid, who ? who->id : "-", who ? (c.name[0] ? c.name : who->name) : "nobody yet",
                  static_cast<unsigned long>(c.taps));
  }
}

// The card with this number, as shown by `cards`.
bool byNumber(long number, friends::Card &out) {
  for (const friends::Card &c : cardList.list())
    if (c.number == number) return out = c, true;
  log_w("no card %ld (cards lists them)", number);
  return false;
}

void handleCommand(const String &raw) {
  String line = raw;
  line.trim();
  String lower = line;
  lower.toLowerCase();
  if (lower.isEmpty()) return;
  if (lower == "help" || lower == "?") return printHelp();
  if (lower == "status") return printStatus();
  if (lower == "cards") return printCards();
  if (lower == "cast") {
    for (const cast::Character &c : cast::kCast) Serial.printf("  %-8s %s\n", c.id, c.name);
    return;
  }
  if (lower == "reset") return reader.requestChipReset();
  if (lower == "token") {
    Serial.printf("Admin token: %s\nPut it in esp32-labs/apps/friends-app/.env as BENCH_TOKEN=... (keep it out of chats and git)\n", token.value().c_str());
    return;
  }
  if (lower == "token new") {
    token.regenerate();
    Serial.printf("New admin token: %s (the old one stops working now; W2 and R7 share it)\n", token.value().c_str());
    return;
  }
  // give <number> <id>, name <number> <name>, forget <number>
  const int space = line.indexOf(' ');
  const String verb = lower.substring(0, space < 0 ? lower.length() : space);
  const String rest = space < 0 ? String() : line.substring(space + 1);
  const int space2 = rest.indexOf(' ');
  const long number = rest.toInt();
  const String arg = space2 < 0 ? String() : rest.substring(space2 + 1);
  friends::Card c;
  if (verb == "forget" && number > 0) {
    if (byNumber(number, c)) cardList.remove(c.uid, c.uidLen), log_i("card %ld forgotten", number);
    return;
  }
  if (verb == "give" && number > 0 && !arg.isEmpty()) {
    String id = arg;
    id.toLowerCase();
    if (id == "none") id = "";
    if (!id.isEmpty() && !cast::find(id.c_str())) {
      log_w("unknown friend '%s' (cast lists them)", id.c_str());
      return;
    }
    if (!byNumber(number, c)) return;
    cardList.update(c.uid, c.uidLen, [&](friends::Card &x) { strlcpy(x.character, id.c_str(), sizeof(x.character)); });
    reader.show(c.uid, c.uidLen);
    return;
  }
  if (verb == "name" && number > 0 && !arg.isEmpty()) {
    if (arg.length() > 15) {
      log_w("names: up to 15 characters");
      return;
    }
    if (!byNumber(number, c)) return;
    const String name = arg == "-" ? String() : arg;
    cardList.update(c.uid, c.uidLen, [&](friends::Card &x) { strlcpy(x.name, name.c_str(), sizeof(x.name)); });
    reader.show(c.uid, c.uidLen);
    return;
  }
  log_w("unknown command '%s' (type help)", line.c_str());
}

void pollSerial() {
  static String buffer;
  while (Serial.available()) {
    const char c = Serial.read();
    if (c == '\n' || c == '\r') {
      if (!buffer.isEmpty()) handleCommand(buffer);
      buffer = "";
    } else if (c == 0x08 || c == 0x7F) {
      if (!buffer.isEmpty()) buffer.remove(buffer.length() - 1);
    } else if (uint8_t(c) >= 0x20 && buffer.length() < 96) {
      buffer += c;
    }
  }
}

void handleButton(Button &b) {
  if (b.poll() == Button::Event::Click) {
    state.view = (state.view + 1) % kViews;
    log_i("view %d: %s", state.view + 1, kViewNames[state.view]);
  }
}

// The status every app sees, once a second and whenever the stage changes.
void publishStatus() {
  JsonDocument d;
  const bool joined = connection.state() == Connection::State::Connected;
  const Stage &s = state.stage;
  JsonObject chip = d["chip"].to<JsonObject>();
  char v[3];
  snprintf(v, sizeof(v), "%02X", s.chipVersion);
  chip["version"] = v;
  chip["name"] = rc522::versionName(s.chipVersion);
  chip["ok"] = s.chipVersion != 0x00 && s.chipVersion != 0xFF;
  JsonObject wifi = d["wifi"].to<JsonObject>();
  wifi["ssid"] = connection.ssid();
  wifi["ip"] = joined ? WiFi.localIP().toString() : String();
  wifi["rssi"] = joined ? WiFi.RSSI() : 0;
  JsonObject rd = d["reader"].to<JsonObject>();
  rd["wait"] = s.irqMode ? "irq" : "poll";
  rd["restores"] = s.restores;
  rd["lost"] = s.lost;
  rd["problem"] = static_cast<const char *>(s.problem);
  rd["problemAgo"] = s.problem[0] ? (millis() - s.problemAt) / 1000 : 0;
  if (s.present) d["present"] = static_cast<const char *>(s.presentUid);
  else d["present"] = nullptr;
  d["cards"] = cardList.count();
  d["maxCards"] = friends::List::kMax;
  d["view"] = kViewNames[state.view];
  JsonObject board = d["board"].to<JsonObject>();
  board["uptime"] = millis() / 1000;
  board["reset"] = resetReason();
  board["heap"] = ESP.getFreeHeap();
  String out;
  serializeJson(d, out);
  api.publishStatus(out);
}

// The on-board LED: the friend's colour for 1.5 s after a tap, a soft teal breath otherwise.
void showLed() {
  static uint32_t shown = 0xFFFFFFFF;
  const Stage &s = state.stage;
  uint8_t r = 0, g = 0, b = 0;
  const uint32_t since = millis() - s.showAt;
  if (s.showSeq && since < 1500) {
    const cast::Character *who = cast::find(s.character);
    const uint16_t c = who ? who->body : pal::teal;
    const float fade = 1.0f - since / 1500.0f;
    r = uint8_t(((c >> 11) << 3) * fade * 0.6f), g = uint8_t((((c >> 5) & 63) << 2) * fade * 0.6f), b = uint8_t(((c & 31) << 3) * fade * 0.6f);
  } else if (s.chipVersion == 0x00 || s.chipVersion == 0xFF) {
    r = 60;
  } else {
    const float k = 0.5f + 0.5f * sinf(millis() / 700.0f);
    g = uint8_t(4 + k * 14), b = uint8_t(4 + k * 12);
  }
  const uint32_t colour = (uint32_t(r) << 16) | (uint32_t(g) << 8) | b;
  if (colour == shown) return;
  shown = colour;
  rgbLedWrite(PIN_RGB, r, g, b);
}

}  // namespace

void setup() {
  Serial.begin(115200);
  delay(1500);
  if (!display.begin()) {
    log_e("No memory for the frame buffer. Stopping.");
    return;
  }
  rgbLedWrite(PIN_RGB, 0, 0, 0);
  external.begin();
  boot.begin();
  token.begin();
  cardList.begin();
  connection.begin();
  reader.begin();
  log_i("rfid-lab-r8: reader task on core 0. Last start: %s. Type token for the app's .env, help for commands.", resetReason());
  printHelp();
}

void loop() {
  FrameBuffer &fb = display.fb();
  if (fb.pixels() == nullptr) {
    delay(1000);
    return;
  }
  const uint32_t now = millis();
  pollSerial();
  handleButton(external);
  handleButton(boot);
  connection.loop();
  if (!state.apiStarted && connection.state() == Connection::State::Connected) {
    api.begin();
    state.apiStarted = true;
    log_i("App: http://%s.local or http://%s  (set BENCH_URL in friends-app/.env)", Connection::kHostname, WiFi.localIP().toString().c_str());
  }
  const bool changed = reader.update(state.stage);
  if (changed && state.stage.showSeq && now - state.stage.showAt < 200) state.view = 0;  // a tap brings the stage back
  if (state.apiStarted) {
    api.loop();
    if (changed || now - state.lastStatus >= 1000) {
      state.lastStatus = now;
      publishStatus();
    }
  }
  if (cardList.version() != state.cardsVersion) {
    state.cardsVersion = cardList.version();
    state.cards = cardList.list();
  }
  showLed();

  const float t = now / 1000.0f;
  fb.fillScreen(pal::night);
  if (state.view == 0) fv::stage(fb, state.stage, state.cards, t);
  else fv::list(fb, state.cards, state.stage, t);
  fv::header(fb, kViewNames[state.view], state.view, kViews, state.stage.present);
  char left[48], right[32];
  const bool joined = connection.state() == Connection::State::Connected;
  if (joined) snprintf(left, sizeof(left), "http://%s.local", Connection::kHostname);
  else snprintf(left, sizeof(left), "%s", connection.ssid().isEmpty() ? "no Wi-Fi saved: run W1 once" : "joining Wi-Fi...");
  snprintf(right, sizeof(right), "%d cards  %u app", cardList.count(), unsigned(api.clients()));
  fv::footer(fb, left, right, joined ? pal::teal : pal::amber);
  display.push();
}

// R8's cast: the friends that can live on a card. The ids are shared with the app
// (esp32-labs/apps/friends-app/src/friends/characters.ts, which checks this file in its tests): the board
// only stores the id, the app draws the 3D version, and this file draws the screen version.
//
// Each friend is a few circles and triangles in its own colours, so a 320 x 170 screen at 20+ fps
// can bounce, blink and squash them without any bitmap in flash.
#pragma once

#include <math.h>
#include <string.h>

#include "color.h"
#include "frame_buffer.h"

namespace cast {

enum class Kind : uint8_t { Fox, Robot, Dragon, Penguin, Alien, Cat, Frog, Unicorn };

struct Character {
  const char *id;    // what the board stores and the app sends
  const char *name;  // the friend's own name, shown when the card has no name of its own
  Kind kind;
  uint16_t body, accent, belly;
};

inline constexpr Character kCast[] = {
    {"fox", "Foxy", Kind::Fox, rgb(250, 130, 40), rgb(60, 36, 28), rgb(255, 240, 225)},
    {"robot", "Bolt", Kind::Robot, rgb(120, 200, 220), rgb(255, 210, 60), rgb(225, 240, 245)},
    {"dragon", "Ember", Kind::Dragon, rgb(90, 200, 110), rgb(255, 90, 70), rgb(240, 230, 150)},
    {"penguin", "Pip", Kind::Penguin, rgb(50, 70, 120), rgb(255, 160, 40), rgb(245, 248, 255)},
    {"alien", "Zib", Kind::Alien, rgb(170, 240, 80), rgb(150, 90, 230), rgb(220, 255, 190)},
    {"cat", "Mochi", Kind::Cat, rgb(255, 160, 200), rgb(120, 60, 90), rgb(255, 235, 245)},
    {"frog", "Hopper", Kind::Frog, rgb(60, 180, 90), rgb(255, 110, 140), rgb(200, 240, 150)},
    {"unicorn", "Luna", Kind::Unicorn, rgb(245, 235, 255), rgb(255, 200, 70), rgb(190, 150, 255)},
};
inline constexpr int kCount = sizeof(kCast) / sizeof(kCast[0]);

// nullptr for "" (no friend yet) or an id this firmware doesn't know.
inline const Character *find(const char *id) {
  if (!id || !id[0]) return nullptr;
  for (const Character &c : kCast)
    if (strcmp(c.id, id) == 0) return &c;
  return nullptr;
}

// One friend standing at (cx, ground): `s` is its size (head radius in pixels), `t` seconds for
// the idle bounce and blinking, `squash` > 1 makes it wide and short (landing), < 1 tall (jump).
inline void draw(FrameBuffer &fb, const Character &c, int cx, int ground, int s, float t, float squash = 1.0f) {
  const int rx = int(s * squash), ry = int(s / squash);
  const int cy = ground - ry;
  const bool blink = fmodf(t + cx * 0.013f, 3.2f) < 0.12f;
  fb.fillEllipse(cx, ground + 2, rx, max(2, s / 6), pal::dim);  // shadow

  // What sits behind the head: ears, horns, wings, antennae.
  switch (c.kind) {
    case Kind::Fox:
    case Kind::Cat:
      for (int side = -1; side <= 1; side += 2) {
        const int ex = cx + side * rx * 6 / 10;
        fb.fillTriangle(ex - s / 3, cy - ry * 6 / 10, ex + s / 3, cy - ry * 6 / 10, ex + side * s / 8, cy - ry - s / 2, c.body);
        fb.fillTriangle(ex - s / 7, cy - ry * 7 / 10, ex + s / 7, cy - ry * 7 / 10, ex + side * s / 12, cy - ry - s / 5,
                        c.kind == Kind::Fox ? c.accent : c.belly);
      }
      if (c.kind == Kind::Fox) fb.fillEllipse(cx + rx + s / 4, cy + ry / 3, s / 2, s / 4, c.body);  // tail
      break;
    case Kind::Robot: {
      fb.drawFastVLine(cx, cy - ry - s / 2, s / 2, c.accent);
      fb.fillCircle(cx, cy - ry - s / 2, max(2, s / 7), (int(t * 3) % 2) ? c.accent : pal::coral);
      break;
    }
    case Kind::Dragon:
      for (int side = -1; side <= 1; side += 2) {
        const float flap = sinf(t * 6) * s * 0.25f;
        fb.fillTriangle(cx + side * rx * 7 / 10, cy, cx + side * (rx + s * 9 / 10), int(cy - s * 0.7f - flap), cx + side * (rx + s / 3),
                        cy + s / 3, c.accent);
        fb.fillTriangle(cx + side * s / 3, cy - ry * 8 / 10, cx + side * s / 6, cy - ry * 8 / 10, cx + side * s / 2, cy - ry - s / 3, c.belly);
      }
      break;
    case Kind::Alien:
      for (int side = -1; side <= 1; side += 2) {
        const int tx = cx + side * s / 2 + int(sinf(t * 4 + side) * s / 8);
        fb.drawLine(cx + side * s / 4, cy - ry * 8 / 10, tx, cy - ry - s / 2, c.body);
        fb.fillCircle(tx, cy - ry - s / 2, max(2, s / 7), c.accent);
      }
      break;
    case Kind::Unicorn:
      for (int i = 0; i < 4; i++) fb.fillCircle(cx - rx * 7 / 10 - i * s / 8, cy - ry / 2 + i * s / 4, s / 4, hsv(uint8_t(170 + i * 25), 140, 255));
      fb.fillTriangle(cx - s / 7, cy - ry * 8 / 10, cx + s / 7, cy - ry * 8 / 10, cx, cy - ry - s * 3 / 4, c.accent);
      break;
    case Kind::Frog:
      for (int side = -1; side <= 1; side += 2) fb.fillCircle(cx + side * s / 2, cy - ry * 8 / 10, s / 3, c.body);
      break;
    case Kind::Penguin: break;
  }

  // Head and body in one round shape, plus a lighter face or belly.
  if (c.kind == Kind::Robot) {
    fb.fillRoundRect(cx - rx, cy - ry, rx * 2, ry * 2, s / 3, c.body);
    fb.fillRoundRect(cx - rx * 7 / 10, cy - ry / 2, rx * 14 / 10, ry * 11 / 10, s / 5, c.belly);
  } else {
    fb.fillEllipse(cx, cy, rx, ry, c.body);
    fb.fillEllipse(cx, cy + ry / 4, rx * 7 / 10, ry * 6 / 10, c.belly);
  }

  // Eyes: the alien has one big one, the frog's sit on top.
  const int eyeY = c.kind == Kind::Frog ? cy - ry * 8 / 10 : cy - ry / 6;
  const int eyeR = max(2, s / 6);
  if (c.kind == Kind::Alien) {
    fb.fillCircle(cx, eyeY, eyeR * 2, pal::ink);
    if (!blink) fb.fillCircle(cx + s / 12, eyeY, eyeR, pal::night);
  } else {
    for (int side = -1; side <= 1; side += 2) {
      const int ex = cx + side * s * (c.kind == Kind::Frog ? 5 : 3) / 10;
      if (blink) {
        fb.fillRect(ex - eyeR, eyeY, eyeR * 2, max(1, s / 16), pal::night);
      } else {
        if (c.kind == Kind::Robot) fb.fillRect(ex - eyeR, eyeY - eyeR, eyeR * 2, eyeR * 2, pal::night);
        else fb.fillCircle(ex, eyeY, eyeR, pal::night);
        fb.fillCircle(ex + eyeR / 3, eyeY - eyeR / 3, max(1, eyeR / 3), pal::ink);
      }
    }
  }

  // Mouth or beak, and cheeks.
  const int my = cy + ry / 4;
  switch (c.kind) {
    case Kind::Penguin: fb.fillTriangle(cx - s / 6, my - s / 12, cx + s / 6, my - s / 12, cx, my + s / 6, c.accent); break;
    case Kind::Fox: fb.fillCircle(cx, my - s / 12, max(2, s / 10), c.accent); break;
    case Kind::Robot: fb.fillRect(cx - s / 4, my, s / 2, max(2, s / 10), c.accent); break;
    default: fb.drawCircleHelper(cx, my - s / 8, s / 4, 4 | 8, pal::night); break;
  }
  if (c.kind != Kind::Robot && c.kind != Kind::Alien) {
    const uint16_t cheek = mix(c.body, pal::coral, 150);
    fb.fillCircle(cx - rx * 6 / 10, my, max(2, s / 9), cheek);
    fb.fillCircle(cx + rx * 6 / 10, my, max(2, s / 9), cheek);
  }
}

}  // namespace cast

// R8's two screens (320 x 170):
//   stage    idle: "tap a card" with the cast walking by. After a tap: the card's friend pops out
//            with a burst of stars in its colours, its name and how many times it came to play.
//            A new card says "new card!", a card with nobody on it says "who lives here?".
//   friends  every card with its friend, number and taps
#pragma once

#include <Fonts/FreeSans9pt7b.h>
#include <Fonts/FreeSansBold18pt7b.h>
#include <Fonts/FreeSansBold9pt7b.h>
#include <math.h>

#include <vector>

#include "characters.h"
#include "color.h"
#include "frame_buffer.h"
#include "friends.h"
#include "tap_reader.h"

namespace fv {

constexpr int kW = 320, kH = 170;
constexpr uint32_t kShowMs = 6000;  // a show stays this long, then back to idle

inline void text(FrameBuffer &fb, int x, int y, uint16_t c, const char *s, const GFXfont *f = nullptr) {
  fb.setFont(f);
  fb.setTextColor(c);
  fb.setCursor(x, y);
  fb.print(s);
}

inline int width(FrameBuffer &fb, const char *s, const GFXfont *f) {
  fb.setFont(f);
  int16_t x1, y1;
  uint16_t w, h;
  fb.getTextBounds(s, 0, 0, &x1, &y1, &w, &h);
  return w;
}

inline void centered(FrameBuffer &fb, int cx, int y, uint16_t c, const char *s, const GFXfont *f) {
  text(fb, cx - width(fb, s, f) / 2, y, c, s, f);
}

// A five-point star (two triangles and a pentagon's worth of fill is plenty at this size).
inline void star(FrameBuffer &fb, int x, int y, int r, uint16_t c) {
  fb.fillTriangle(x, y - r, x - r * 6 / 10, y + r * 8 / 10, x + r * 6 / 10, y + r * 8 / 10, c);
  fb.fillTriangle(x - r, y - r / 4, x + r, y - r / 4, x, y + r / 2, c);
  fb.fillTriangle(x, y + r / 2, x - r * 6 / 10, y + r * 8 / 10, x + r * 6 / 10, y + r * 8 / 10, c);
}

inline void header(FrameBuffer &fb, const char *view, int index, int count, bool present) {
  text(fb, 8, 18, pal::ink, "FRIENDS ", &FreeSansBold9pt7b);
  fb.setFont(&FreeSans9pt7b);
  fb.setTextColor(pal::muted);
  fb.print(view);
  const int first = 286 - (count - 1) * 10;
  for (int i = 0; i < count; i++) fb.fillCircle(first + i * 10, 14, 3, i == index ? pal::ink : pal::dim);
  fb.fillCircle(304, 14, 5, present ? pal::teal : pal::dim);
}

inline void footer(FrameBuffer &fb, const char *left, const char *right, uint16_t rightColor) {
  fb.fillRect(0, kH - 11, kW, 11, pal::night);
  text(fb, 6, kH - 9, pal::muted, left);
  fb.setFont(nullptr);
  int16_t x1, y1;
  uint16_t w, h;
  fb.getTextBounds(right, 0, 0, &x1, &y1, &w, &h);
  text(fb, kW - 6 - w, kH - 9, rightColor, right);
}

// Easing for the pop: overshoots a little, then settles at 1.
inline float popIn(float k) {
  if (k >= 1) return 1;
  const float c = 1.7f;
  const float x = k - 1;
  return 1 + (c + 1) * x * x * x + c * x * x;
}

// Idle: a card outline that breathes, and the friends already living on cards walking by.
inline void idle(FrameBuffer &fb, const std::vector<friends::Card> &cards, float t) {
  const float breathe = 0.5f + 0.5f * sinf(t * 2.4f);
  const uint16_t glow = mix(pal::dim, pal::teal, uint8_t(breathe * 200));
  fb.drawRoundRect(118, 40, 84, 54, 8, glow);
  fb.drawRoundRect(119, 41, 82, 52, 7, glow);
  for (int i = 0; i < 3; i++) {
    const float k = fmodf(t * 0.7f + i / 3.0f, 1.0f);
    fb.drawCircle(160, 67, 10 + int(k * 26), mix(pal::teal, pal::night, uint8_t(k * 255)));
  }
  centered(fb, 160, 116, pal::ink, "Tap a card!", &FreeSansBold9pt7b);

  std::vector<const cast::Character *> walkers;
  for (const friends::Card &c : cards)
    if (const cast::Character *who = cast::find(c.character)) walkers.push_back(who);
  if (walkers.empty()) {
    centered(fb, 160, 140, pal::muted, "a friend will pop out of it", &FreeSans9pt7b);
    return;
  }
  const int n = int(walkers.size());
  for (int i = 0; i < n; i++) {
    const float x = fmodf(t * 26 + i * (360.0f / n), 360.0f) - 20;
    const float hop = fabsf(sinf(t * 5 + i));
    cast::draw(fb, *walkers[i], int(x), 152 - int(hop * 6), 12, t, 1.0f + (1 - hop) * 0.12f);
  }
}

// After a tap: the friend pops out with stars; a new or empty card asks for one.
inline void show(FrameBuffer &fb, const Stage &s, float t) {
  const float since = (millis() - s.showAt) / 1000.0f;
  const cast::Character *who = cast::find(s.character);
  const uint16_t c = who ? who->body : pal::teal;
  // A soft glow in the friend's colour behind it.
  for (int r = 70; r > 20; r -= 10) fb.fillCircle(84, 100, r, mix(pal::night, c, uint8_t(40 + (70 - r) * 1.2f)));

  // Stars fly out from the card, then fall.
  for (int i = 0; i < 14; i++) {
    const float a = i * 0.449f + 0.3f;
    const float k = since * (0.9f + (i % 4) * 0.15f);
    if (k > 1.6f) continue;
    const int x = 84 + int(cosf(a) * k * 110);
    const int y = 100 - int(sinf(a) * k * 90 - k * k * 40);
    star(fb, x, y, 3 + i % 3, i % 2 ? (who ? who->accent : pal::amber) : pal::ink);
  }

  if (s.full) {
    centered(fb, 220, 80, pal::amber, "12 cards!", &FreeSansBold9pt7b);
    centered(fb, 220, 104, pal::muted, "forget one in the app", &FreeSans9pt7b);
    return;
  }
  if (!who) {
    // Nobody lives here yet: an empty card with a question mark that wobbles.
    const int wob = int(sinf(t * 6) * 4);
    fb.fillRoundRect(52, 68 + wob, 64, 44, 6, pal::ink);
    centered(fb, 84, 102 + wob, pal::night, "?", &FreeSansBold18pt7b);
    char line[24];
    snprintf(line, sizeof(line), "card %u", s.number);
    centered(fb, 228, 66, pal::muted, line, &FreeSans9pt7b);
    centered(fb, 228, 94, pal::ink, s.isNew ? "New card!" : "Who lives", &FreeSansBold9pt7b);
    centered(fb, 228, 116, pal::ink, s.isNew ? "Give it a friend" : "here?", s.isNew ? &FreeSans9pt7b : &FreeSansBold9pt7b);
    centered(fb, 228, 140, pal::muted, "drag one in the app", &FreeSans9pt7b);
    return;
  }

  // Jump out of the card: scale pops in, then a happy bounce.
  const float pop = popIn(since / 0.6f);
  const float hop = since > 0.6f ? fabsf(sinf((since - 0.6f) * 6)) : 0;
  const float squash = since > 0.6f ? 1.0f + (1 - hop) * 0.15f : 1.0f;
  cast::draw(fb, *who, 84, 146 - int(hop * 14), max(4, int(34 * pop)), t, squash);

  const char *name = s.name[0] ? s.name : who->name;
  centered(fb, 228, 72, mix(c, pal::ink, 120), s.isNew ? "Hello!" : "Hi again!", &FreeSans9pt7b);
  centered(fb, 228, 104, pal::ink, name, &FreeSansBold18pt7b);
  char line[32];
  if (s.fromApp) snprintf(line, sizeof(line), "card %u", s.number);
  else snprintf(line, sizeof(line), "card %u  -  %lu visit%s", s.number, static_cast<unsigned long>(s.taps), s.taps == 1 ? "" : "s");
  centered(fb, 228, 130, pal::muted, line, &FreeSans9pt7b);
}

inline void stage(FrameBuffer &fb, const Stage &s, const std::vector<friends::Card> &cards, float t) {
  if (s.showSeq && millis() - s.showAt < kShowMs) show(fb, s, t);
  else idle(fb, cards, t);
}

// Every card with its friend: up to 12 in a 6 x 2 grid.
inline void list(FrameBuffer &fb, const std::vector<friends::Card> &cards, const Stage &s, float t) {
  if (cards.empty()) {
    centered(fb, 160, 90, pal::muted, "No cards yet: tap one!", &FreeSans9pt7b);
    return;
  }
  for (size_t i = 0; i < cards.size(); i++) {
    const friends::Card &c = cards[i];
    const int col = int(i % 6), row = int(i / 6);
    const int x = 8 + col * 51, y = 34 + row * 62;
    char uid[21];
    friends::uidToHex(c.uid, c.uidLen, uid, sizeof(uid));
    const bool onReader = s.present && strcmp(uid, s.presentUid) == 0;
    fb.drawRoundRect(x, y, 47, 58, 6, onReader ? pal::teal : pal::dim);
    if (const cast::Character *who = cast::find(c.character)) {
      cast::draw(fb, *who, x + 23, y + 40, 11, t + i);
      const char *name = c.name[0] ? c.name : who->name;
      char shortName[8];
      strlcpy(shortName, name, sizeof(shortName));
      fb.setFont(nullptr);
      text(fb, x + 23 - int(strlen(shortName)) * 3, y + 46, pal::ink, shortName);
    } else {
      text(fb, x + 20, y + 22, pal::muted, "?", &FreeSansBold9pt7b);
    }
    char n[8];
    snprintf(n, sizeof(n), "%u", c.number);
    text(fb, x + 4, y + 4, pal::muted, n);
  }
}

}  // namespace fv

// R8's card list: which friend lives on which card. Up to 12 cards, kept in NVS (namespace
// "friends", separate from R7's door list) so they survive power-off and re-flashing.
//
// A card the board has never seen is added by itself on its first tap, with no friend yet: the
// app then shows an empty card that a friend can be dragged onto. The card only brings its UID;
// the board remembers who lives there.
//
// Two tasks use the list (the web server edits it, the reader task counts taps), so every method
// takes the mutex. The UID helpers come from R7 (access_rules.h): same hex format in both labs.
#pragma once

#include <Preferences.h>

#include <functional>
#include <mutex>
#include <vector>

#include "access_rules.h"
#include "characters.h"

namespace friends {

using door::uidFromHex;
using door::uidToHex;

struct Card {
  uint8_t uid[10] = {};
  uint8_t uidLen = 0;
  uint8_t number = 0;       // 1, 2, 3 ... in the order the cards were first tapped
  char character[12] = "";  // a cast id ("fox"), "" = nobody lives here yet
  char name[16] = "";       // the friend's name on this card, "" = the character's own name
  uint32_t taps = 0;
};

class List {
 public:
  static constexpr int kMax = 12;
  static constexpr uint8_t kFormat = 1;  // bump when Card changes: an old list is then ignored

  enum class TapResult { Known, Added, Full };

  void begin() {
    std::lock_guard<std::mutex> lock(mutex_);
    Preferences p;
    p.begin("friends", true);
    const uint8_t format = p.getUChar("format", 0);
    if (format == kFormat) {
      count_ = std::min<int>(p.getUChar("count", 0), kMax);
      if (count_ && p.getBytes("cards", cards_, sizeof(Card) * count_) != sizeof(Card) * count_) count_ = 0;
      nextNumber_ = p.getUChar("next", uint8_t(count_ + 1));
    } else if (format != 0) {
      log_w("friend list saved by an older firmware (format %u): starting fresh", format);
    }
    p.end();
    log_i("friend list: %d card%s", count_, count_ == 1 ? "" : "s");
  }

  int count() {
    std::lock_guard<std::mutex> lock(mutex_);
    return count_;
  }
  uint32_t version() {
    std::lock_guard<std::mutex> lock(mutex_);
    return version_;
  }

  std::vector<Card> list() {
    std::lock_guard<std::mutex> lock(mutex_);
    return std::vector<Card>(cards_, cards_ + count_);
  }

  bool get(const uint8_t *uid, uint8_t len, Card &out) {
    std::lock_guard<std::mutex> lock(mutex_);
    const int i = find(uid, len);
    if (i < 0) return false;
    out = cards_[i];
    return true;
  }

  // A tap: count it, or add the card when it is new. `out` is the card after the tap.
  TapResult tap(const uint8_t *uid, uint8_t len, Card &out) {
    std::lock_guard<std::mutex> lock(mutex_);
    int i = find(uid, len);
    TapResult r = TapResult::Known;
    if (i < 0) {
      if (count_ >= kMax) return TapResult::Full;
      i = count_++;
      cards_[i] = Card{};
      memcpy(cards_[i].uid, uid, len);
      cards_[i].uidLen = len;
      cards_[i].number = nextNumber_++;
      r = TapResult::Added;
    }
    cards_[i].taps++;
    out = cards_[i];
    save();
    return r;
  }

  // Change one card in place; false when it isn't in the list.
  bool update(const uint8_t *uid, uint8_t len, const std::function<void(Card &)> &change, Card *after = nullptr) {
    std::lock_guard<std::mutex> lock(mutex_);
    const int i = find(uid, len);
    if (i < 0) return false;
    change(cards_[i]);
    if (after) *after = cards_[i];
    save();
    return true;
  }

  bool remove(const uint8_t *uid, uint8_t len) {
    std::lock_guard<std::mutex> lock(mutex_);
    const int i = find(uid, len);
    if (i < 0) return false;
    for (int k = i; k + 1 < count_; k++) cards_[k] = cards_[k + 1];
    count_--;
    if (count_ == 0) nextNumber_ = 1;
    save();
    return true;
  }

 private:
  int find(const uint8_t *uid, uint8_t len) const {
    for (int i = 0; i < count_; i++)
      if (cards_[i].uidLen == len && memcmp(cards_[i].uid, uid, len) == 0) return i;
    return -1;
  }

  void save() {
    Preferences p;
    p.begin("friends", false);
    p.putUChar("format", kFormat);
    p.putUChar("count", uint8_t(count_));
    p.putUChar("next", nextNumber_);
    if (count_) p.putBytes("cards", cards_, sizeof(Card) * count_);
    else if (p.isKey("cards")) p.remove("cards");
    p.end();
    version_++;
  }

  std::mutex mutex_;
  Card cards_[kMax];
  int count_ = 0;
  uint8_t nextNumber_ = 1;
  uint32_t version_ = 1;
};

}  // namespace friends

// R8's web side, for the kids' app in esp32-labs/apps/friends-app: a small JSON API and a WebSocket on
// port 80, the same libraries and the same admin token as R7 (kit/lib/wifi-kit/api_token.h).
//
// Endpoints (JSON). Reading is open on your Wi-Fi; every change needs the admin token, which the
// app's dev server adds from esp32-labs/apps/friends-app/.env (the browser never holds it).
//   GET    /api                  this list
//   GET    /api/status           reader chip, Wi-Fi, board, the card on the reader, the last show
//   GET    /api/cards            the cards and who lives on each
//   GET    /api/cast             the friend ids this firmware can draw
//   PUT    /api/card?uid=HEX     {"character": "fox" | "", "name": "Max"}: move a friend onto the card
//   DELETE /api/card?uid=HEX     forget the card (it comes back, empty, on its next tap)
//   POST   /api/show?uid=HEX     show this card's friend on the screen and in every app
//   POST   /api/chip-reset       hard reset of the reader chip
//   WS     /ws                   pushes {"type": "status" | "cards" | "tap", "data": ...}
#pragma once

#include <ArduinoJson.h>
#include <AsyncJson.h>
#include <ESPAsyncWebServer.h>

#include <mutex>

#include "api_token.h"
#include "characters.h"
#include "friends.h"
#include "tap_reader.h"

class FriendsApi {
 public:
  FriendsApi(friends::List &list, TapReader &reader, const ApiToken &token) : list_(list), reader_(reader), token_(token) {}

  void begin() {
    ws_.onEvent([this](AsyncWebSocket *, AsyncWebSocketClient *client, AwsEventType type, void *, uint8_t *, size_t) {
      if (type != WS_EVT_CONNECT) return;
      std::lock_guard<std::mutex> lock(mutex_);  // the latest picture straight away
      if (!status_.isEmpty()) client->text(wrap("status", status_));
      client->text(wrap("cards", cardsJson()));
    });
    server_.addHandler(&ws_);

    auto get = [this](const char *path, ArRequestHandlerFunction fn) { server_.on(AsyncURIMatcher::exact(path), HTTP_GET, fn); };
    auto post = [this](const char *path, ArRequestHandlerFunction fn) { server_.on(AsyncURIMatcher::exact(path), HTTP_POST, fn); };

    server_.on(AsyncURIMatcher::exact("/"), HTTP_GET, [](AsyncWebServerRequest *req) {
      req->send(200, "text/plain", "rfid-lab-r8, card friends. Use the app in esp32-labs/apps/friends-app, or the JSON API at /api\n");
    });
    get("/api", [](AsyncWebServerRequest *req) { req->send(200, "application/json", kIndex); });
    get("/api/status", [this](AsyncWebServerRequest *req) {
      std::lock_guard<std::mutex> lock(mutex_);
      if (status_.isEmpty()) return error(req, 503, "starting up");
      req->send(200, "application/json", status_);
    });
    get("/api/cards", [this](AsyncWebServerRequest *req) { req->send(200, "application/json", cardsJson()); });
    get("/api/cast", [](AsyncWebServerRequest *req) {
      JsonDocument d;
      JsonArray a = d.to<JsonArray>();
      for (const cast::Character &c : cast::kCast) {
        JsonObject o = a.add<JsonObject>();
        o["id"] = c.id, o["name"] = c.name;
      }
      send(req, 200, d);
    });

    auto *edit = new AsyncCallbackJsonWebHandler("/api/card", [this](AsyncWebServerRequest *req, JsonVariant &body) {
      if (!admin(req)) return;
      if (!body.is<JsonObject>()) return error(req, 400, "send a JSON object");
      editCard(req, body.as<JsonObjectConst>());
    });
    edit->setMethod(HTTP_PUT);
    edit->setMaxContentLength(256);
    server_.addHandler(edit);
    server_.on(AsyncURIMatcher::exact("/api/card"), HTTP_DELETE, [this](AsyncWebServerRequest *req) {
      uint8_t uid[10], len = 0;
      if (!admin(req) || !uidParam(req, uid, len)) return;
      if (!list_.remove(uid, len)) return error(req, 404, "no card with this uid in the list");
      req->send(200, "application/json", "{\"ok\":true}");
    });
    post("/api/show", [this](AsyncWebServerRequest *req) {
      uint8_t uid[10], len = 0;
      if (!admin(req) || !uidParam(req, uid, len)) return;
      if (!reader_.show(uid, len)) return error(req, 404, "no card with this uid in the list");
      req->send(200, "application/json", "{\"ok\":true}");
    });
    post("/api/chip-reset", [this](AsyncWebServerRequest *req) {
      if (!admin(req)) return;
      reader_.requestChipReset();
      req->send(200, "application/json", "{\"ok\":true}");
    });

    server_.onNotFound([](AsyncWebServerRequest *req) { error(req, 404, "no such endpoint, see /api"); });
    server_.begin();
    log_i("Web server on port 80: API at /api, live updates at /ws");
  }

  // ---- From loop() ------------------------------------------------------------------------------

  void publishStatus(const String &json) {
    {
      std::lock_guard<std::mutex> lock(mutex_);
      status_ = json;
    }
    if (ws_.count()) ws_.textAll(wrap("status", json));
  }

  void loop() {
    const uint32_t now = millis();
    if (now - lastCleanup_ > 2000) lastCleanup_ = now, ws_.cleanupClients();
    String msg;
    while (reader_.takeMessage(msg))
      if (ws_.count()) ws_.textAll(msg);
    const uint32_t v = list_.version();
    if (v != listVersion_) {
      listVersion_ = v;
      if (ws_.count()) ws_.textAll(wrap("cards", cardsJson()));
    }
  }

  size_t clients() const { return ws_.count(); }

 private:
  void editCard(AsyncWebServerRequest *req, JsonObjectConst b) {
    uint8_t uid[10], len = 0;
    if (!uidParam(req, uid, len)) return;
    // Check everything first, then change the card in one go.
    const char *character = b["character"] | static_cast<const char *>(nullptr);
    if (character && character[0] && !cast::find(character)) return error(req, 400, "character: one of the ids in GET /api/cast, or \"\"");
    const char *name = b["name"] | static_cast<const char *>(nullptr);
    if (name && !validName(name)) return error(req, 400, "name: up to 15 plain characters (A-Z, digits, space, - . ')");
    friends::Card after;
    const bool found = list_.update(uid, len, [&](friends::Card &c) {
      if (character) strlcpy(c.character, character, sizeof(c.character));
      if (name) strlcpy(c.name, name, sizeof(c.name));
    }, &after);
    if (!found) return error(req, 404, "no card with this uid in the list");
    JsonDocument d;
    d["ok"] = true;
    card(d["card"].to<JsonObject>(), after);
    send(req, 200, d);
  }

  static void card(JsonObject o, const friends::Card &c) {
    char uid[21];
    friends::uidToHex(c.uid, c.uidLen, uid, sizeof(uid));
    o["uid"] = uid;
    o["number"] = c.number;
    o["character"] = static_cast<const char *>(c.character);  // copied, see R7's log entry 44
    o["name"] = static_cast<const char *>(c.name);
    o["taps"] = c.taps;
  }

  String cardsJson() {
    JsonDocument d;
    JsonArray a = d.to<JsonArray>();
    for (const friends::Card &c : list_.list()) card(a.add<JsonObject>(), c);
    String out;
    serializeJson(d, out);
    return out;
  }

  // Names go to a small screen font: plain ASCII only, "" = use the character's own name.
  static bool validName(const char *s) {
    const size_t n = strlen(s);
    if (n > 15) return false;
    for (size_t i = 0; i < n; i++)
      if (!(isalnum(uint8_t(s[i])) || strchr(" -.'_", s[i]))) return false;
    return true;
  }

  bool admin(AsyncWebServerRequest *req) {
    if (req->hasHeader("Authorization") && token_.allows(req->header("Authorization"))) return true;
    error(req, 401, "admin action: send Authorization: Bearer <token> (serial command: token)");
    return false;
  }

  bool uidParam(AsyncWebServerRequest *req, uint8_t *uid, uint8_t &len) {
    if (req->hasParam("uid") && friends::uidFromHex(req->getParam("uid")->value().c_str(), uid, len)) return true;
    error(req, 400, "uid: 8, 14 or 20 hex digits, e.g. ?uid=9C4F2A1B");
    return false;
  }

  static void send(AsyncWebServerRequest *req, int code, JsonDocument &d) {
    String out;
    serializeJson(d, out);
    req->send(code, "application/json", out);
  }

  static void error(AsyncWebServerRequest *req, int code, const char *message) {
    JsonDocument d;
    d["error"] = message;
    send(req, code, d);
  }

  static String wrap(const char *type, const String &data) { return String("{\"type\":\"") + type + "\",\"data\":" + data + "}"; }

  static constexpr const char *kIndex =
      "{\"endpoints\":[\"GET /api/status\",\"GET /api/cards\",\"GET /api/cast\",\"PUT /api/card?uid=HEX {character,name}\","
      "\"DELETE /api/card?uid=HEX\",\"POST /api/show?uid=HEX\",\"POST /api/chip-reset\",\"WS /ws\"],"
      "\"admin\":\"every change: Authorization: Bearer <token>\"}";

  friends::List &list_;
  TapReader &reader_;
  const ApiToken &token_;
  AsyncWebServer server_{80};
  AsyncWebSocket ws_{"/ws"};
  std::mutex mutex_;
  String status_;
  uint32_t lastCleanup_ = 0, listVersion_ = 0;
};

// R8's reader task: the only code that touches the RC522 (core 0, SPI3, as in R1-R7). It
//   - polls for cards about 12 times a second and turns each new card into a "show": who lives
//     on it, its name, whether it was just added
//   - keeps the reader healthy the way R7 learned to: falls back from the IRQ wire to polling,
//     puts the chip's settings back after a 3.3 V dip, hard-resets a chip that stopped answering
// No card data is read or written here: R8 only needs the UID.
// loop() copies the latest Stage for the screen; the web side takes the messages from the outbox.
#pragma once

#include <ArduinoJson.h>

#include <atomic>
#include <mutex>
#include <vector>

#include "friends.h"
#include "iso14443a.h"
#include "mfrc522.h"
#include "pins.h"

// What the screen and the app need to know right now.
struct Stage {
  uint32_t version = 0;
  // Reader health, as in R7.
  uint8_t chipVersion = 0;
  bool irqMode = false;
  uint16_t restores = 0, lost = 0;
  char problem[72] = "";
  uint32_t problemAt = 0;  // millis()
  bool present = false;
  char presentUid[21] = "";
  // The last show: a tap on the reader, or a card the app asked to show.
  uint32_t showSeq = 0;
  uint32_t showAt = 0;  // millis()
  char uid[21] = "";
  char character[12] = "";
  char name[16] = "";
  uint8_t number = 0;
  uint32_t taps = 0;
  bool isNew = false;   // first tap of this card: it was just added
  bool full = false;    // a new card, but the list is full (12)
  bool fromApp = false; // shown from the app, not tapped
};

class TapReader {
 public:
  explicit TapReader(friends::List &list) : list_(list) {}

  void begin() { xTaskCreatePinnedToCore(task, "taps", 8 * 1024, this, 2, nullptr, 0); }

  bool update(Stage &mine) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (mine.version == stage_.version) return false;
    mine = stage_;
    return true;
  }

  // From the web server: show a card's friend on the screen and in every app, as if tapped
  // (the tap count stays). false when the card isn't in the list.
  bool show(const uint8_t *uid, uint8_t len) {
    friends::Card c;
    if (!list_.get(uid, len, c)) return false;
    announce(c, false, false, true);
    return true;
  }

  void requestChipReset() { resetWanted_ = true; }

  bool takeMessage(String &out) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (outbox_.empty()) return false;
    out = std::move(outbox_.front());
    outbox_.erase(outbox_.begin());
    return true;
  }

 private:
  static void task(void *self) { static_cast<TapReader *>(self)->run(); }

  void run() {
    spi_ = new SPIClass(HSPI);  // the S3's SPI3: the screen keeps SPI2 to itself
    const uint8_t v = chip_.begin(*spi_, {PIN_RFID_SS, PIN_RFID_SCK, PIN_RFID_MOSI, PIN_RFID_MISO, PIN_RFID_RST, PIN_RFID_IRQ}, nullptr);
    if (chip_.hasIrqPin()) chip_.setWaitMode(rc522::Mfrc522::WaitMode::Irq);
    log_i("RC522: VersionReg 0x%02X (%s)", v, rc522::versionName(v));
    chipLost_ = !alive(v);
    if (chipLost_) problem("reader chip not answering: check its 3.3V, GND and MISO wires");
    publish([&](Stage &s) { s.chipVersion = v, s.irqMode = chip_.waitMode() == rc522::Mfrc522::WaitMode::Irq; });
    for (;;) {
      if (resetWanted_.exchange(false)) {
        chip_.hardReset();
        const uint8_t again = chip_.read(rc522::VersionReg);
        chipLost_ = !alive(again);
        publish([&](Stage &s) { s.chipVersion = again; });
        log_i("RC522 hard reset from the app: 0x%02X", again);
      }
      if (millis() - lastHealth_ >= 2000) health();
      if (!chipLost_) pollOnce();
      vTaskDelay(pdMS_TO_TICKS(80));
    }
  }

  static bool alive(uint8_t v) { return v != 0x00 && v != 0xFF; }

  template <typename F>
  void publish(F change) {
    std::lock_guard<std::mutex> lock(mutex_);
    change(stage_);
    stage_.version++;
  }

  void send(JsonDocument &data) {
    JsonDocument msg;
    msg["type"] = "tap";
    msg["data"] = data;
    String text;
    serializeJson(msg, text);
    std::lock_guard<std::mutex> lock(mutex_);
    if (outbox_.size() >= 16) outbox_.erase(outbox_.begin());
    outbox_.push_back(std::move(text));
  }

  void problem(const char *what) {
    log_w("reader: %s", what);
    publish([&](Stage &s) {
      strlcpy(s.problem, what, sizeof(s.problem));
      s.problemAt = millis();
    });
  }

  // ---- Cards -----------------------------------------------------------------------------------

  void pollOnce() {
    iso14443a::Uid u;
    const bool found = iso14443a::wakeAndSelect(chip_, u) == rc522::Status::Ok;
    if (found) iso14443a::halt(chip_);
    checkIrq();
    const bool isNew = found && (!present_ || !u.sameAs(current_));
    if (found) misses_ = 0;
    if (isNew) {
      present_ = true, current_ = u;
      char hex[21];
      friends::uidToHex(u.bytes, u.size, hex, sizeof(hex));
      publish([&](Stage &s) { s.present = true, strlcpy(s.presentUid, hex, sizeof(s.presentUid)); });
      onTap(u, hex);
    } else if (!found && present_ && ++misses_ >= 3) {
      present_ = false;
      publish([](Stage &s) { s.present = false, s.presentUid[0] = 0; });
    }
  }

  void onTap(const iso14443a::Uid &u, const char *hex) {
    friends::Card c;
    const friends::List::TapResult r = list_.tap(u.bytes, u.size, c);
    if (r == friends::List::TapResult::Full) {
      memcpy(c.uid, u.bytes, u.size);
      c.uidLen = u.size;
      log_w("card %s: the list is full (12 cards), forget one in the app", hex);
    }
    announce(c, r == friends::List::TapResult::Added, r == friends::List::TapResult::Full, false);
  }

  // One show: the screen's stage and a "tap" message to every app.
  void announce(const friends::Card &c, bool isNew, bool full, bool fromApp) {
    char hex[21];
    friends::uidToHex(c.uid, c.uidLen, hex, sizeof(hex));
    uint32_t seq = 0;
    publish([&](Stage &s) {
      seq = ++s.showSeq;
      s.showAt = millis();
      strlcpy(s.uid, hex, sizeof(s.uid));
      strlcpy(s.character, c.character, sizeof(s.character));
      strlcpy(s.name, c.name, sizeof(s.name));
      s.number = c.number, s.taps = c.taps, s.isNew = isNew, s.full = full, s.fromApp = fromApp;
    });
    const cast::Character *who = cast::find(c.character);
    log_i("%s card %u (%s): %s%s", fromApp ? "show" : "tap", c.number, hex, who ? (c.name[0] ? c.name : who->name) : "nobody yet",
          isNew ? ", new card" : full ? ", list full" : "");
    // Char arrays go in as const char *: ArduinoJson then copies them (see R7, log entry 44).
    JsonDocument d;
    d["seq"] = seq;
    d["uid"] = static_cast<const char *>(hex);
    d["character"] = static_cast<const char *>(c.character);
    d["name"] = static_cast<const char *>(c.name);
    d["number"] = c.number;
    d["taps"] = c.taps;
    d["isNew"] = isNew;
    d["full"] = full;
    d["fromApp"] = fromApp;
    send(d);
  }

  // ---- Reader health (R7's lessons) -------------------------------------------------------------

  // The IRQ wire stayed quiet although the chip finished: poll the chip instead.
  void checkIrq() {
    if (!chip_.takeIrqMissed() || chip_.waitMode() != rc522::Mfrc522::WaitMode::Irq) return;
    chip_.setWaitMode(rc522::Mfrc522::WaitMode::Poll);
    publish([](Stage &s) { s.irqMode = false; });
    char msg[72];
    snprintf(msg, sizeof(msg), "IRQ wire on GPIO %d stays quiet: polling instead", PIN_RFID_IRQ);
    problem(msg);
  }

  // Every 2 s: settings lost after a 3.3 V dip? Chip silent? Then put it right.
  void health() {
    lastHealth_ = millis();
    const uint8_t v = chip_.read(rc522::VersionReg);
    if (alive(v) && !chipLost_) {
      if (chip_.settingsLost()) {
        chip_.restoreSettings();
        publish([](Stage &s) { s.restores++; });
        problem("the reader chip reset itself (3.3V dip?): settings restored");
      }
      return;
    }
    if (alive(v) == !chipLost_) return;
    if (!alive(v)) {
      chip_.hardReset();
      const uint8_t again = chip_.read(rc522::VersionReg);
      chipLost_ = !alive(again);
      publish([&](Stage &s) { s.chipVersion = again, s.lost++; });
      problem(chipLost_ ? "reader chip stopped answering: check its 3.3V, GND and MISO wires"
                        : "reader chip had hung: a hard reset brought it back");
    } else {
      chipLost_ = false;
      log_i("RC522 answering again: 0x%02X", v);
      publish([&](Stage &s) { s.chipVersion = v; });
    }
  }

  friends::List &list_;
  rc522::Mfrc522 chip_;
  SPIClass *spi_ = nullptr;
  std::mutex mutex_;
  Stage stage_;
  std::vector<String> outbox_;
  std::atomic<bool> resetWanted_{false};
  bool chipLost_ = false, present_ = false;
  iso14443a::Uid current_;
  uint8_t misses_ = 0;
  uint32_t lastHealth_ = 0;
};

// The admin token: a random secret that guards the actions that could change the bench (W2:
// firmware update, forgetting the Wi-Fi network, rebooting; R7: every change to the card list).
//
// It is created on first boot from the chip's hardware random number generator and kept in NVS
// (namespace "api", so every lab on this board shares it). It is printed over serial with the
// `token` command, never sent by the API. The Mac side keeps a copy in a git-ignored .env file
// and adds it to admin requests as "Authorization: Bearer <token>". `token new` makes a fresh one.
#pragma once

#include <Arduino.h>
#include <Preferences.h>
#include <esp_random.h>

class ApiToken {
 public:
  void begin() {
    Preferences prefs;
    prefs.begin("api", true);
    token_ = prefs.getString("token", "");
    prefs.end();
    if (token_.length() != 32) regenerate();
  }

  void regenerate() {
    char hex[33];
    for (int i = 0; i < 16; i++) snprintf(hex + i * 2, 3, "%02x", uint8_t(esp_random()));
    token_ = hex;
    Preferences prefs;
    prefs.begin("api", false);
    prefs.putString("token", token_);
    prefs.end();
  }

  const String &value() const { return token_; }

  // Compares in constant time, so response timing doesn't leak how many characters matched.
  bool allows(const String &authorizationHeader) const {
    const String expected = "Bearer " + token_;
    if (authorizationHeader.length() != expected.length()) return false;
    uint8_t diff = 0;
    for (size_t i = 0; i < expected.length(); i++) diff |= uint8_t(authorizationHeader[i] ^ expected[i]);
    return diff == 0;
  }

 private:
  String token_;
};

// A push button on any GPIO, wired between the pin and GND.
//
// Wiring: we turn on the chip's internal pull-up resistor, so the pin reads HIGH when the
// button is up and LOW when pressed (the button connects it to GND). No resistor needed.
//
// Bounce: the metal contacts inside a button flicker on/off for a few milliseconds on
// every press and release. Our screen loop only looks about 22 times a second, far too
// slowly to see that. So an interrupt counts every single edge the instant it happens,
// and poll() only trusts a new state once the pin has been quiet for kDebounceMs.
//
// Gestures, reported by poll():
//   Click        press and release, then nothing else for kDoubleGapMs
//   DoubleClick  two clicks within kDoubleGapMs
//   LongPress    held for kLongPressMs (fires while still held, so it feels instant)
#pragma once

#include <Arduino.h>
#include <esp_timer.h>

class Button {
 public:
  enum class Event { None, Click, DoubleClick, LongPress };

  Button(uint8_t pin, const char *name) : pin_(pin), name_(name) {}

  void begin() {
    pinMode(pin_, INPUT_PULLUP);
    // CHANGE = run onEdge on every rising and falling edge, bounces included.
    attachInterruptArg(digitalPinToInterrupt(pin_), onEdge, this, CHANGE);
  }

  const char *name() const { return name_; }
  bool isDown() const { return pressed_; }
  // Raw edges seen during the last press + release, minus the 2 a perfect button makes.
  uint32_t lastBounces() const { return lastBounces_; }

  Event poll() {
    const uint32_t nowUs = uint32_t(esp_timer_get_time());
    const uint32_t now = millis();

    // 1. Debounce: accept the pin's level once no edge has arrived for kDebounceMs.
    const bool level = digitalRead(pin_) == LOW;
    if (level != pressed_ && nowUs - lastEdgeUs_ >= kDebounceMs * 1000) {
      pressed_ = level;
      if (pressed_) {
        pressedAt_ = now;
        longFired_ = false;
      } else {
        // Every edge since the previous release belongs to this press + release.
        const uint32_t edges = edges_ - edgesAtRest_;
        edgesAtRest_ = edges_;
        lastBounces_ = edges > 2 ? edges - 2 : 0;
        if (!longFired_) {
          clicks_++;
          releasedAt_ = now;
        }
      }
    }

    // 2. Turn clean presses into gestures.
    if (pressed_ && !longFired_ && now - pressedAt_ >= kLongPressMs) {
      longFired_ = true;
      clicks_ = 0;
      return Event::LongPress;
    }
    if (!pressed_ && clicks_ >= 2) {
      clicks_ = 0;
      return Event::DoubleClick;
    }
    if (!pressed_ && clicks_ == 1 && now - releasedAt_ >= kDoubleGapMs) {
      clicks_ = 0;
      return Event::Click;
    }
    return Event::None;
  }

 private:
  static constexpr uint32_t kDebounceMs = 25;
  static constexpr uint32_t kLongPressMs = 600;
  static constexpr uint32_t kDoubleGapMs = 280;

  // Runs inside the interrupt: keep it tiny. IRAM_ATTR keeps it in fast internal RAM.
  static void IRAM_ATTR onEdge(void *arg) {
    auto *self = static_cast<Button *>(arg);
    self->edges_ = self->edges_ + 1;
    self->lastEdgeUs_ = uint32_t(esp_timer_get_time());  // 32 bits: read in one go, wraps safely
  }

  uint8_t pin_;
  const char *name_;
  volatile uint32_t edges_ = 0;      // written by the interrupt
  volatile uint32_t lastEdgeUs_ = 0;  // written by the interrupt
  bool pressed_ = false;
  bool longFired_ = false;
  uint8_t clicks_ = 0;
  uint32_t edgesAtRest_ = 0;
  uint32_t lastBounces_ = 0;
  uint32_t pressedAt_ = 0;
  uint32_t releasedAt_ = 0;
};

// Colour helpers for the 16-bit RGB565 format the ST7789 speaks: 5 bits red, 6 green, 5 blue.
#pragma once

#include <stdint.h>

constexpr uint16_t rgb(uint8_t r, uint8_t g, uint8_t b) {
  return uint16_t(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3));
}

// Hue 0-255 around the colour wheel, saturation and value 0-255.
inline uint16_t hsv(uint8_t h, uint8_t s, uint8_t v) {
  const uint8_t region = h / 43;
  const uint8_t rem = (h - region * 43) * 6;
  const uint8_t p = (v * (255 - s)) >> 8;
  const uint8_t q = (v * (255 - ((s * rem) >> 8))) >> 8;
  const uint8_t t = (v * (255 - ((s * (255 - rem)) >> 8))) >> 8;
  switch (region) {
    case 0: return rgb(v, t, p);
    case 1: return rgb(q, v, p);
    case 2: return rgb(p, v, t);
    case 3: return rgb(p, q, v);
    case 4: return rgb(t, p, v);
    default: return rgb(v, p, q);
  }
}

// Mix two colours: k = 0 gives a, k = 255 gives b.
inline uint16_t mix(uint16_t a, uint16_t b, uint8_t k) {
  const int ar = a >> 11, ag = (a >> 5) & 63, ab = a & 31;
  const int br = b >> 11, bg = (b >> 5) & 63, bb = b & 31;
  return uint16_t(((ar + ((br - ar) * k >> 8)) << 11) | ((ag + ((bg - ag) * k >> 8)) << 5) | (ab + ((bb - ab) * k >> 8)));
}

